// src/components/HeroSection.jsx
import React from "react";
import { Link } from "react-router-dom";

const HeroSection = () => {
  return (
    <section className="flex flex-col justify-center items-center text-center py-24 px-8 bg-green-100">
      <h2 className="text-4xl md:text-5xl font-bold text-green-800 mb-4">
        AI-Powered Sustainable Packaging
      </h2>
      <p className="text-gray-700 max-w-2xl mb-8">
        EcoPackAI helps businesses choose eco-friendly, cost-effective packaging
        materials while minimizing carbon footprint.
      </p>
      <div className="space-x-4">
        <Link
          to="/login"
          className="bg-green-600 text-white px-6 py-3 rounded-xl shadow-md hover:bg-green-700"
        >
          Get Started
        </Link>
        <Link
          to="/demo"
          className="border border-green-600 text-green-700 px-6 py-3 rounded-xl hover:bg-green-50"
        >
          Try Demo
        </Link>
      </div>
    </section>
  );
};

export default HeroSection;
